 function readPrices(){if(!priceMin)return true;const parse=(input,fallback)=>{const raw=input.value.trim();if(!raw)return fallback;if(!/^(?:\d+|\d{1,3}(?:[., ]\d{3})+)(?:\s*[₫đĐ])?$/.test(raw))return NaN;return Number(raw.replace(/[^\d]/g,""))};const min=parse(priceMin,0),max=parse(priceMax,Infinity);let message="";if(!Number.isSafeInteger(min)||(!Number.isSafeInteger(max)&&max!==Infinity))message="Nhập giá bằng số nguyên không âm, ví dụ 50.000 ₫.";else if(min>max)message="Giá thấp nhất không được lớn hơn giá cao nhất.";text(priceError,message);priceError.hidden=!message;for(const input of [priceMin,priceMax])input.setAttribute("aria-invalid",String(Boolean(message)));if(message)return false;minimum=min;maximum=max;return true;}
